<?php $cat=$_GET['cat']??'local'; $labels=['ultima'=>'Última hora','local'=>'Local','servicios'=>'Servicios e infraestructura','politica'=>'Política metropolitana','comunidad'=>'Comunidad','opinion'=>'Opinión']; $pageTitle=$labels[$cat]??ucfirst($cat); require_once __DIR__.'/includes/config.php';$articles=visible_articles($cat);include __DIR__.'/includes/header.php';?><section class="wrap section-page"><span class="kicker">SECCIÓN</span><h1><?= h($pageTitle) ?></h1><?php if($cat==='opinion'): ?><p class="section-intro">Entrevistas, análisis de especialistas, voces ciudadanas, reportajes especiales y la sátira de Pingo para entender —y cuestionar— la agenda metropolitana.</p><?php endif; ?><div class="list"><?php if(!$articles):?><p>No hay publicaciones disponibles en esta sección por el momento.</p><?php endif;foreach($articles as $a): $m=media_info($a['hero_asset']);?><article data-news-id="<?=(int)$a['id']?>" data-news-new="<?=article_is_new($a,$state)?'1':'0'?>" data-interafas="<?=((int)$a['phase_required']>0 || !empty($a['event_required']))?'1':'0'?>"><a href="/nota.php?slug=<?=h($a['slug'])?>"><img src="<?= h($m['src']) ?>" onerror="this.onerror=null;this.src='<?= h($m['fallback']) ?>'" alt=""><div><div class="card-time"><?= article_time($a) ?> · <?=h(strtoupper($a['category']))?></div><h2><?=h($a['headline'])?></h2><p><?=h($a['subheadline'])?></p></div></a></article><?php endforeach;?></div></section><script>window.PULSO_LIVE=true;</script><?php include __DIR__.'/includes/footer.php';?>
